from solution import summarize_inventory
import hashlib
import hmac
import json
import pytest


def signed(payload, secret=b"hangar-key"):
    return hmac.new(secret, payload.encode("utf-8"), hashlib.sha256).hexdigest()


def test_empty_inventory_returns_empty_list():
    payload = json.dumps({"parts": []}, separators=(",", ":"))
    assert summarize_inventory(payload, signed(payload), b"hangar-key") == []


def test_aggregates_filters_and_strips_part_numbers():
    data = {"parts": [
        {"part_number": "  A-12 ", "quantity": 4, "status": "serviceable"},
        {"part_number": "A-12", "quantity": 3, "status": "repairable"},
        {"part_number": "A-12", "quantity": 2, "status": "serviceable"},
        {"part_number": "B-7", "quantity": 9, "status": "scrapped"},
        {"part_number": "B-7", "quantity": 1, "status": "serviceable"}
    ]}
    payload = json.dumps(data, separators=(",", ":"))
    assert summarize_inventory(payload, signed(payload), b"hangar-key") == [
        {"part_number": "A-12", "quantity": 6},
        {"part_number": "B-7", "quantity": 1}
    ]


def test_sorting_uses_part_number_for_ties():
    data = {"parts": [
        {"part_number": "Z-9", "quantity": 5, "status": "serviceable"},
        {"part_number": "A-1", "quantity": 5, "status": "serviceable"},
        {"part_number": "M-4", "quantity": 8, "status": "serviceable"}
    ]}
    payload = json.dumps(data)
    assert summarize_inventory(payload, signed(payload), b"hangar-key") == [
        {"part_number": "M-4", "quantity": 8},
        {"part_number": "A-1", "quantity": 5},
        {"part_number": "Z-9", "quantity": 5}
    ]


def test_pagination_boundaries():
    data = {"parts": [
        {"part_number": "A", "quantity": 4, "status": "serviceable"},
        {"part_number": "B", "quantity": 3, "status": "serviceable"},
        {"part_number": "C", "quantity": 2, "status": "serviceable"},
        {"part_number": "D", "quantity": 1, "status": "serviceable"}
    ]}
    payload = json.dumps(data)
    sig = signed(payload)
    assert summarize_inventory(payload, sig, b"hangar-key", 1, 2) == [
        {"part_number": "A", "quantity": 4}, {"part_number": "B", "quantity": 3}
    ]
    assert summarize_inventory(payload, sig, b"hangar-key", 2, 2) == [
        {"part_number": "C", "quantity": 2}, {"part_number": "D", "quantity": 1}
    ]
    assert summarize_inventory(payload, sig, b"hangar-key", 3, 2) == []


def test_bad_signature_is_rejected():
    payload = '{"parts":[]}'
    with pytest.raises(PermissionError):
        summarize_inventory(payload, "0" * 64, b"hangar-key")
    with pytest.raises(PermissionError):
        summarize_inventory(payload, "not-a-signature", b"hangar-key")


def test_malformed_payload_raises_value_error_after_valid_signature():
    payload = "not json"
    with pytest.raises(ValueError):
        summarize_inventory(payload, signed(payload), b"hangar-key")


def test_invalid_records_and_paging_raise_value_error():
    for data in [
        {"parts": {}},
        {"parts": [{"part_number": "A", "quantity": True, "status": "serviceable"}]},
        {"parts": [{"part_number": " ", "quantity": 1, "status": "serviceable"}]},
        {"parts": [{"part_number": "A", "quantity": 1, "status": "unknown"}]}
    ]:
        payload = json.dumps(data)
        with pytest.raises(ValueError):
            summarize_inventory(payload, signed(payload), b"hangar-key")
    payload = '{"parts":[]}'
    sig = signed(payload)
    with pytest.raises(ValueError):
        summarize_inventory(payload, sig, b"hangar-key", 0)
    with pytest.raises(ValueError):
        summarize_inventory(payload, sig, b"hangar-key", 1, 101)

