import hashlib
import hmac
import json

def summarize_inventory(payload: str, signature: str, secret: bytes, page: int=1, page_size: int=3) -> list[dict[str, int | str]]:
    expected = hmac.new(secret, payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not isinstance(signature, str) or len(signature) != 64 or any((c not in '0123456789abcdef' for c in signature)) or (not hmac.compare_digest(expected, signature)):
        raise PermissionError('invalid signature')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid paging')
    try:
        document = json.loads(payload)
    except (json.JSONDecodeError, UnicodeDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(document, dict) or not isinstance(document.get('parts'), list):
        raise ValueError('invalid parts')
    totals = {}
    for item in document['parts']:
        if not isinstance(item, dict):
            raise ValueError('invalid part')
        number = item.get('part_number')
        quantity = item.get('quantity')
        status = item.get('status')
        if not isinstance(number, str) or not number.strip() or type(quantity) is not int or (quantity < 0) or (status not in {'serviceable', 'repairable', 'scrapped'}):
            raise ValueError('invalid part')
        number = number.strip()
        if status == 'serviceable':
            totals[number] = totals.get(number, 0) + quantity
    rows = [{'part_number': number, 'quantity': quantity} for number, quantity in totals.items() if quantity > 0]
    rows.sort(key=lambda row: (-row['quantity'], row['part_number']))
    start = (page - 1) * page_size
    return rows[start:start + page_size]

