from datetime import datetime
from decimal import Decimal, ROUND_HALF_UP
from lxml import etree

def schedule_summary(xml_text: str, specialty: str | None, page: int, page_size: int) -> dict:
    if page < 1 or page_size < 1:
        raise ValueError('invalid pagination')
    try:
        root = etree.fromstring(xml_text.encode(), parser=etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False))
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'consultations':
        raise ValueError('invalid root')
    records = []
    for node in root:
        if node.tag != 'consultation':
            continue
        required = ['id', 'doctor', 'specialty', 'start', 'duration_minutes', 'fee']
        if any((node.get(key) is None for key in required)):
            raise ValueError('missing attribute')
        try:
            start = node.get('start')
            datetime.fromisoformat(start)
            duration = int(node.get('duration_minutes'))
            fee = Decimal(node.get('fee'))
        except Exception as exc:
            raise ValueError('invalid consultation') from exc
        if duration <= 0 or fee < 0:
            raise ValueError('invalid consultation')
        if specialty is None or node.get('specialty') == specialty:
            records.append((datetime.fromisoformat(start), node.get('id'), node, duration, fee))
    records.sort(key=lambda item: (item[0], item[1]))
    total_minutes = sum((item[3] for item in records))
    total_fee = sum((item[4] for item in records), Decimal('0'))
    begin = (page - 1) * page_size
    selected = records[begin:begin + page_size]
    items = []
    for _, _, node, duration, fee in selected:
        items.append({'id': node.get('id'), 'doctor': node.get('doctor'), 'specialty': node.get('specialty'), 'start': node.get('start'), 'duration_minutes': duration, 'fee': float(fee.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))})

    def rounded(value):
        return float(value.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
    return {'total': len(records), 'page': page, 'page_size': page_size, 'items': items, 'total_minutes': total_minutes, 'total_fee': rounded(total_fee)}

