from solution import create_appraisal_record, can_view_appraisal


def test_create_record_preserves_appraisal_fields():
    record = create_appraisal_record("LOT-482", 375000, "1947")
    assert record["property_id"] == "LOT-482"
    assert record["appraised_value"] == 375000
    assert set(record) == {"property_id", "appraised_value", "access_pin_hash"}
    assert record["access_pin_hash"] != "1947"


def test_correct_pin_allows_access():
    record = create_appraisal_record("P-1", 210000, "839201")
    assert can_view_appraisal(record, "839201") is True


def test_wrong_pin_is_rejected():
    record = create_appraisal_record("P-2", 210000, "839201")
    assert can_view_appraisal(record, "839202") is False
    assert can_view_appraisal(record, "") is False


def test_empty_pin_round_trips():
    record = create_appraisal_record("P-3", 1, "")
    assert can_view_appraisal(record, "") is True
    assert can_view_appraisal(record, "0") is False


def test_extra_record_fields_are_ignored():
    record = create_appraisal_record("P-4", 999999, "pin")
    record["status"] = "pending"
    record["agent"] = "A17"
    assert can_view_appraisal(record, "pin") is True


def test_create_rejects_invalid_property_ids():
    for value in ("", None, 123):
        try:
            create_appraisal_record(value, 100, "1234")
        except (ValueError, TypeError):
            pass
        else:
            assert False


def test_create_rejects_invalid_values_and_pin_types():
    for value in (0, -1, True, False, 1.5):
        try:
            create_appraisal_record("P", value, "1234")
        except (ValueError, TypeError):
            pass
        else:
            assert False
    try:
        create_appraisal_record("P", 100, 1234)
    except TypeError:
        pass
    else:
        assert False


def test_malformed_records_return_false():
    valid = create_appraisal_record("P-5", 500, "secret")
    cases = [
        None,
        [],
        {},
        {"property_id": "P-5", "appraised_value": 500},
        {"property_id": "", "appraised_value": 500, "access_pin_hash": valid["access_pin_hash"]},
        {"property_id": "P-5", "appraised_value": 0, "access_pin_hash": valid["access_pin_hash"]},
        {"property_id": "P-5", "appraised_value": 500, "access_pin_hash": None},
    ]
    for record in cases:
        assert can_view_appraisal(record, "secret") is False
    assert can_view_appraisal(valid, None) is False

