import base64
import hashlib
import hmac
import os

def _credential(pin):
    salt = os.urandom(16)
    rounds = 100000
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, rounds)
    return f'{rounds}${base64.b64encode(salt).decode()}${digest.hex()}'

def _matches(pin, stored):
    try:
        rounds_text, salt_text, digest_text = stored.split('$', 2)
        rounds = int(rounds_text)
        salt = base64.b64decode(salt_text.encode(), validate=True)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, rounds)
        return rounds >= 100000 and hmac.compare_digest(actual, expected)
    except (AttributeError, ValueError, TypeError):
        return False

def create_appraisal_record(property_id: str, appraised_value: int, access_pin: str) -> dict:
    if not isinstance(property_id, str):
        raise TypeError('property_id must be a string')
    if not property_id:
        raise ValueError('property_id must not be empty')
    if not isinstance(appraised_value, int) or isinstance(appraised_value, bool):
        raise TypeError('appraised_value must be an integer')
    if appraised_value <= 0:
        raise ValueError('appraised_value must be positive')
    if not isinstance(access_pin, str):
        raise TypeError('access_pin must be a string')
    return {'property_id': property_id, 'appraised_value': appraised_value, 'access_pin_hash': _credential(access_pin)}

def can_view_appraisal(record: dict, access_pin: str) -> bool:
    if not isinstance(record, dict) or not isinstance(access_pin, str):
        return False
    property_id = record.get('property_id')
    value = record.get('appraised_value')
    if not isinstance(property_id, str) or not property_id:
        return False
    if not isinstance(value, int) or isinstance(value, bool) or value <= 0:
        return False
    return _matches(access_pin, record.get('access_pin_hash'))

