from solution import build_batch_trace_report
import pytest


def test_owner_receives_sorted_aggregated_report():
    requester = {"id": "u1", "tenant_id": "t1", "roles": ["operator"]}
    batches = [{
        "id": "B-7", "tenant_id": "t1", "owner_id": "u1", "product_code": "P-42",
        "events": [
            {"timestamp": "2024-01-02T10:00:00Z", "station": "Weld", "status": "open", "quantity": 3},
            {"timestamp": "2024-01-01T10:00:00Z", "station": "Assembly", "status": "started", "quantity": 2},
            {"timestamp": "2024-01-03T10:00:00Z", "station": "Weld", "status": "closed", "quantity": 4},
        ]
    }]
    assert build_batch_trace_report(requester, batches, "B-7") == {
        "batch_id": "B-7", "product_code": "P-42", "event_count": 3,
        "total_quantity": 9, "stations": [
            {"station": "Assembly", "event_count": 1, "total_quantity": 2, "latest_status": "started"},
            {"station": "Weld", "event_count": 2, "total_quantity": 7, "latest_status": "closed"}
        ], "page": 1, "page_size": 10, "total_stations": 2
    }


def test_quality_role_can_read_batch():
    requester = {"id": "inspector", "tenant_id": "t1", "roles": ["quality_manager"]}
    batch = {"id": "B1", "tenant_id": "t1", "owner_id": "other", "product_code": "X", "events": []}
    result = build_batch_trace_report(requester, [batch], "B1")
    assert result["event_count"] == 0
    assert result["stations"] == []


def test_pagination_and_alphabetical_tie_order():
    requester = {"id": "u", "tenant_id": "t", "roles": ["quality_manager"]}
    events = [{"timestamp": f"2024-01-0{i}T00:00:00Z", "station": station, "status": "ok", "quantity": i} for i, station in enumerate(["C", "A", "D", "B"], 1)]
    batch = {"id": "B", "tenant_id": "t", "owner_id": "u", "product_code": "Q", "events": events}
    result = build_batch_trace_report(requester, [batch], "B", 2, 2)
    assert result["stations"] == [
        {"station": "C", "event_count": 1, "total_quantity": 1, "latest_status": "ok"},
        {"station": "D", "event_count": 1, "total_quantity": 3, "latest_status": "ok"}
    ]
    assert result["page"] == 2 and result["page_size"] == 2 and result["total_stations"] == 4


def test_empty_events_and_empty_later_page():
    requester = {"id": "u", "tenant_id": "t", "roles": ["operator"]}
    batch = {"id": "B", "tenant_id": "t", "owner_id": "u", "product_code": "Q", "events": []}
    assert build_batch_trace_report(requester, [batch], "B", 3, 5)["stations"] == []


def test_missing_batch_and_duplicate_batches():
    requester = {"id": "u", "tenant_id": "t", "roles": ["quality_manager"]}
    with pytest.raises(KeyError):
        build_batch_trace_report(requester, [], "missing")
    batch = {"id": "B", "tenant_id": "t", "owner_id": "u", "product_code": "Q", "events": []}
    with pytest.raises(ValueError):
        build_batch_trace_report(requester, [batch, batch.copy()], "B")


def test_invalid_pagination_and_event_data():
    requester = {"id": "u", "tenant_id": "t", "roles": ["quality_manager"]}
    base = {"id": "B", "tenant_id": "t", "owner_id": "u", "product_code": "Q", "events": []}
    with pytest.raises(ValueError):
        build_batch_trace_report(requester, [base], "B", 0)
    bad = dict(base, events=[{"timestamp": "not-a-time", "station": "A", "status": "x", "quantity": 1}])
    with pytest.raises(ValueError):
        build_batch_trace_report(requester, [bad], "B")

