from datetime import datetime

def build_batch_trace_report(requester: dict, batches: list[dict], batch_id: str, page: int=1, page_size: int=10) -> dict:
    if type(page) is not int or type(page_size) is not int or page < 1 or (page_size < 1):
        raise ValueError('invalid pagination')
    matches = [b for b in batches if b.get('id') == batch_id]
    if len(matches) > 1:
        raise ValueError('duplicate batch id')
    if not matches:
        raise KeyError(batch_id)
    batch = matches[0]
    if not isinstance(batch.get('id'), str):
        raise ValueError('invalid id')
    if requester.get('tenant_id') != batch.get('tenant_id'):
        raise PermissionError('forbidden')
    if requester.get('id') != batch.get('owner_id') and 'quality_manager' not in requester.get('roles', []):
        raise PermissionError('forbidden')
    groups = {}
    total = 0
    events = batch.get('events')
    if not isinstance(events, list):
        raise ValueError('invalid events')
    for event in events:
        try:
            timestamp = datetime.fromisoformat(event['timestamp'].replace('Z', '+00:00'))
            station = event['station']
            status = event['status']
            quantity = event['quantity']
        except (KeyError, TypeError, AttributeError, ValueError):
            raise ValueError('invalid event')
        if not isinstance(station, str) or not isinstance(status, str) or isinstance(quantity, bool) or (not isinstance(quantity, (int, float))):
            raise ValueError('invalid event')
        total += quantity
        group = groups.setdefault(station, {'event_count': 0, 'total_quantity': 0, 'latest': (timestamp, status)})
        group['event_count'] += 1
        group['total_quantity'] += quantity
        if timestamp >= group['latest'][0]:
            group['latest'] = (timestamp, status)
    stations = [{'station': name, 'event_count': groups[name]['event_count'], 'total_quantity': groups[name]['total_quantity'], 'latest_status': groups[name]['latest'][1]} for name in sorted(groups)]
    start = (page - 1) * page_size
    return {'batch_id': batch['id'], 'product_code': batch['product_code'], 'event_count': len(events), 'total_quantity': total, 'stations': stations[start:start + page_size], 'page': page, 'page_size': page_size, 'total_stations': len(stations)}

