    if root.tag != 'event-registration':
        raise ValueError('invalid root')
    values = {}
    names = [('attendee', 'attendee'), ('email', 'email'), ('event-code', 'event_code')]
    for element_name, output_name in names:
        element = root.find(element_name)
        if element is None or element.text is None or (not element.text.strip()):
            raise ValueError('missing required field')
        values[output_name] = element.text.strip()
    notes = root.find('dietary-notes')
    values['dietary_notes'] = '' if notes is None or notes.text is None else notes.text.strip()
    return values

