import csv
import datetime
import os
import re
import tempfile
_HEADER = ['applicant', 'property', 'status', 'submitted', 'affordability']
_STATUSES = ('pending', 'approved', 'rejected')

def _prepare(applications):
    rows = []
    counts = {x: 0 for x in _STATUSES}
    levels = {'strong': 0, 'adequate': 0, 'weak': 0}
    for item in applications:
        try:
            person = item['applicant']
            prop = item['property']
            name = person['name']
            income = person['income']
            address = prop['address']
            rent = prop['monthly_rent']
            submitted = item['submitted']
            status = item['status']
        except (KeyError, TypeError):
            raise ValueError('invalid application')
        if not isinstance(name, str) or not name or (not isinstance(address, str)) or (not address):
            raise ValueError('invalid text')
        if isinstance(income, bool) or isinstance(rent, bool) or (not isinstance(income, (int, float))) or (not isinstance(rent, (int, float))) or (income <= 0) or (rent <= 0):
            raise ValueError('invalid amount')
        if not isinstance(submitted, str) or not re.fullmatch('\\d{4}-\\d{2}-\\d{2}', submitted):
            raise ValueError('invalid date')
        try:
            datetime.date.fromisoformat(submitted)
        except ValueError:
            raise ValueError('invalid date')
        if status not in _STATUSES:
            raise ValueError('invalid status')
        ratio = income / rent
        level = 'strong' if ratio >= 3 else 'adequate' if ratio >= 2 else 'weak'
        counts[status] += 1
        levels[level] += 1
        rows.append((address, submitted, name, [name, address, status, submitted, f'{ratio:.2f}']))
    rows.sort(key=lambda x: x[:3])
    return (rows, counts, levels)

def export_applications(applications: list[dict], destination: str) -> dict:
    rows, counts, levels = _prepare(applications)
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=directory, prefix='.rental-')
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle)
            writer.writerow(_HEADER)
            writer.writerows((row[3] for row in rows))
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return {'written': len(rows), 'by_status': counts, 'by_affordability': levels}

def read_export(path: str) -> list[dict]:
    with open(path, newline='', encoding='utf-8') as handle:
        reader = csv.reader(handle)
        try:
            header = next(reader)
        except StopIteration:
            raise ValueError('empty export')
        if header != _HEADER:
            raise ValueError('bad header')
        result = []
        for fields in reader:
            if len(fields) != 5 or not re.fullmatch('(?:\\d+)(?:\\.\\d{2})', fields[4]):
                raise ValueError('bad row')
            result.append(dict(zip(_HEADER, fields)))
        return result

