from solution import verify_manifest, schedule_launches, process_manifest
import hashlib
import hmac
import json
import pytest


def make_token(payload, secret=b"range-key"):
    raw = json.dumps(payload, separators=(",", ":"), ensure_ascii=False)
    sig = hmac.new(secret, raw.encode(), hashlib.sha256).hexdigest()
    return sig + "|" + raw


def launch(identifier, pad="A", duration=10, window=(0, 100), priority=0):
    return {"id": identifier, "pad": pad, "duration": duration,
            "window": list(window), "priority": priority}


def test_verify_manifest_returns_payload_with_unicode_and_exact_json():
    payload = {"launches": [launch("éclair", window=(-5, 20), priority=3)]}
    token = make_token(payload)
    assert verify_manifest(token, b"range-key") == payload


def test_verify_manifest_rejects_bad_tokens_and_payload_shapes():
    payload = {"launches": []}
    token = make_token(payload)
    with pytest.raises(ValueError):
        verify_manifest(token.replace("|", "", 1), b"range-key")
    with pytest.raises(ValueError):
        verify_manifest("0" * 64 + token[64:], b"range-key")
    with pytest.raises(ValueError):
        verify_manifest(token[:10] + "z" + token[11:], b"range-key")
    bad = make_token({"launches": {}})
    with pytest.raises(ValueError):
        verify_manifest(bad, b"range-key")


def test_verify_manifest_validates_launch_fields_and_duplicate_ids():
    cases = [
        {"launches": [launch("x", duration=0)]},
        {"launches": [launch("x", window=(4, 4))]},
        {"launches": [launch("x"), launch("x", pad="B")]},
        {"launches": [{"id": "x"}]},
    ]
    for payload in cases:
        with pytest.raises(ValueError):
            verify_manifest(make_token(payload), b"range-key")


def test_schedule_orders_by_priority_window_and_identifier():
    manifest = {"launches": [
        launch("late", duration=5, window=(0, 50), priority=1),
        launch("high", duration=5, window=(0, 50), priority=2),
        launch("early-window", duration=5, window=(0, 10), priority=1),
    ]}
    result = schedule_launches(manifest, {"A": [[0, 30]]})
    assert result == [
        {"id": "high", "pad": "A", "start": 0, "end": 5},
        {"id": "early-window", "pad": "A", "start": 5, "end": 10},
        {"id": "late", "pad": "A", "start": 10, "end": 15},
    ]


def test_schedule_uses_multiple_intervals_and_omits_impossible_launches():
    manifest = {"launches": [
        launch("first", duration=6, window=(0, 20)),
        launch("gap", duration=5, window=(8, 20)),
        launch("too-long", duration=9, window=(0, 8)),
        launch("unknown", pad="B", duration=2),
    ]}
    availability = {"A": [[0, 7], [10, 20]], "B": [[0, 1]]}
    assert schedule_launches(manifest, availability) == [
        {"id": "first", "pad": "A", "start": 0, "end": 6},
        {"id": "gap", "pad": "A", "start": 10, "end": 15},
    ]


def test_schedule_tie_breaks_and_output_order_are_deterministic():
    manifest = {"launches": [
        launch("z", pad="B", duration=3, window=(0, 20), priority=4),
        launch("a", pad="A", duration=3, window=(0, 20), priority=4),
    ]}
    assert schedule_launches(manifest, {"A": [[0, 10]], "B": [[0, 10]]}) == [
        {"id": "a", "pad": "A", "start": 0, "end": 3},
        {"id": "z", "pad": "B", "start": 0, "end": 3},
    ]


