import hashlib
import hmac
import json

def verify_manifest(token: str, secret: bytes) -> dict:
    if not isinstance(token, str) or token.count('|') != 1:
        raise ValueError('invalid token')
    text_sig, raw = token.split('|', 1)
    if len(text_sig) != 64:
        raise ValueError('invalid signature')
    try:
        supplied = bytes.fromhex(text_sig)
    except ValueError:
        raise ValueError('invalid signature')
    if not hmac.compare_digest(supplied, hmac.new(secret, raw.encode('utf-8'), hashlib.sha256).digest()):
        raise ValueError('invalid signature')
    try:
        data = json.loads(raw)
    except (TypeError, ValueError):
        raise ValueError('invalid payload')
    if not isinstance(data, dict) or not isinstance(data.get('launches'), list):
        raise ValueError('invalid launches')
    seen = set()
    for item in data['launches']:
        if not isinstance(item, dict) or set(item) != {'id', 'pad', 'duration', 'window', 'priority'}:
            raise ValueError('invalid launch')
        if not isinstance(item['id'], str) or not item['id'] or item['id'] in seen:
            raise ValueError('invalid id')
        if not isinstance(item['pad'], str) or not item['pad']:
            raise ValueError('invalid pad')
        if type(item['duration']) is not int or item['duration'] <= 0:
            raise ValueError('invalid duration')
        w = item['window']
        if not isinstance(w, list) or len(w) != 2 or any((type(x) is not int for x in w)) or (w[0] >= w[1]):
            raise ValueError('invalid window')
        if type(item['priority']) is not int:
            raise ValueError('invalid priority')
        seen.add(item['id'])
    return data

def schedule_launches(manifest: dict, availability: dict[str, list[list[int]]]) -> list[dict]:
    intervals = {}
    for pad, values in availability.items():
        intervals[pad] = []
        for pair in values:
            if not isinstance(pair, list) or len(pair) != 2 or any((type(x) is not int for x in pair)) or (pair[0] >= pair[1]):
                raise ValueError('invalid availability')
            intervals[pad].append(tuple(pair))
    reserved = {pad: [] for pad in intervals}
    chosen = []
    launches = sorted(manifest['launches'], key=lambda x: (-x['priority'], x['window'][1], x['id']))
    for item in launches:
        if item['pad'] not in intervals:
            continue
        w0, w1 = item['window']
        dur = item['duration']
        candidate = None
        for a, b in intervals[item['pad']]:
            start = max(a, w0)
            while start + dur <= min(b, w1):
                conflicts = [r for r in reserved[item['pad']] if start < r[1] and start + dur > r[0]]
                if not conflicts:
                    candidate = start
                    break
                start = min((r[1] for r in conflicts if r[1] > start))
            if candidate is not None:
                break
        if candidate is not None:
            record = {'id': item['id'], 'pad': item['pad'], 'start': candidate, 'end': candidate + dur}
            reserved[item['pad']].append((candidate, candidate + dur))
            chosen.append(record)
    return sorted(chosen, key=lambda x: (x['start'], x['pad'], x['id']))

def process_manifest(token: str, secret: bytes, availability: dict[str, list[list[int]]]) -> list[dict]:
    return schedule_launches(verify_manifest(token, secret), availability)

