    try:
        salt, expected = registry[exhibitor_id]['secret'].split(':')
        actual = hashlib.pbkdf2_hmac('sha256', secret.encode(), bytes.fromhex(salt), 100000).hex()
        return hmac.compare_digest(actual, expected)
