import csv
import io
import os
import tempfile

def parse_ballots(text: str) -> list[dict]:
    if not isinstance(text, str) or not text:
        raise ValueError('invalid input')
    try:
        rows = list(csv.reader(io.StringIO(text, newline='')))
    except csv.Error as exc:
        raise ValueError('invalid csv') from exc
    if not rows or rows[0] != ['voter', 'proposal', 'choice', 'weight']:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if len(row) == 0 or row == []:
            continue
        if len(row) != 4:
            raise ValueError('invalid row')
        voter, proposal, choice, weight = (x.strip() for x in row)
        choice = choice.upper()
        if not voter or not proposal or choice not in {'FOR', 'AGAINST', 'ABSTAIN'}:
            raise ValueError('invalid value')
        try:
            number = int(weight, 10)
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid weight') from exc
        if number <= 0 or (str(number) != weight and (not (weight.startswith('+') and str(number) == weight[1:]))):
            raise ValueError('invalid weight')
        result.append({'voter': voter, 'proposal': proposal, 'choice': choice, 'weight': number})
    if not result:
        raise ValueError('no ballots')
    return result

def tally_votes(ballots: list[dict]) -> list[dict]:
    groups = {}
    seen = set()
    for ballot in ballots:
        try:
            voter = ballot['voter']
            proposal = ballot['proposal']
            choice = ballot['choice']
            weight = ballot['weight']
        except (KeyError, TypeError) as exc:
            raise ValueError('invalid ballot') from exc
        if not isinstance(voter, str) or not voter or (not isinstance(proposal, str)) or (not proposal):
            raise ValueError('invalid ballot')
        if choice not in {'FOR', 'AGAINST', 'ABSTAIN'} or type(weight) is not int or weight <= 0:
            raise ValueError('invalid ballot')
        key = (voter, proposal)
        if key in seen:
            raise ValueError('duplicate ballot')
        seen.add(key)
        item = groups.setdefault(proposal, {'proposal': proposal, 'for': 0, 'against': 0, 'abstain': 0, 'total': 0})
        item[choice.lower()] += weight
        item['total'] += weight
    return sorted(groups.values(), key=lambda x: (-x['for'], -x['against'], x['proposal']))

def export_report(text: str, destination: str) -> str:
    rows = tally_votes(parse_ballots(text))
    output = io.StringIO(newline='')
    writer = csv.writer(output, lineterminator='\n')
    writer.writerow(['proposal', 'for', 'against', 'abstain', 'total'])
    for row in rows:
        writer.writerow([row['proposal'], row['for'], row['against'], row['abstain'], row['total']])
    content = output.getvalue()
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=directory)
    try:
        with os.fdopen(fd, 'w', newline='') as handle:
            handle.write(content)
        os.replace(temporary, destination)
    except Exception:
        if os.path.exists(temporary):
            os.unlink(temporary)
        raise
    return content

