from solution import create_contract_signature

import hashlib
import hmac
import json
import os
from unittest.mock import patch


def expected_signature(key, contract_id, version, fields):
    message = json.dumps(
        {"contract_id": contract_id, "version": version, "fields": fields},
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
    ).encode("utf-8")
    return hmac.new(key.encode("utf-8"), message, hashlib.sha256).hexdigest()


def test_basic_contract_signature():
    fields = {"customer": "Acme", "amount": 1250}
    with patch.dict(os.environ, {"CONTRACT_SIGNING_KEY": "alpha-key"}, clear=False):
        assert create_contract_signature("C-100", 1, fields) == expected_signature(
            "alpha-key", "C-100", 1, fields
        )


def test_empty_fields_are_supported():
    with patch.dict(os.environ, {"CONTRACT_SIGNING_KEY": "empty-key"}, clear=False):
        assert create_contract_signature("C-101", 3, {}) == expected_signature(
            "empty-key", "C-101", 3, {}
        )


def test_field_insertion_order_does_not_change_result():
    first = {"z": 2, "a": 1, "middle": "x"}
    second = {"middle": "x", "a": 1, "z": 2}
    with patch.dict(os.environ, {"CONTRACT_SIGNING_KEY": "order-key"}, clear=False):
        assert create_contract_signature("C-102", 2, first) == create_contract_signature(
            "C-102", 2, second
        )


def test_unicode_values_are_encoded_consistently():
    fields = {"title": "Vertrag – München", "emoji": "✓"}
    with patch.dict(os.environ, {"CONTRACT_SIGNING_KEY": "unicode-key"}, clear=False):
        assert create_contract_signature("контракт-1", 7, fields) == expected_signature(
            "unicode-key", "контракт-1", 7, fields
        )


def test_nested_and_mixed_field_values():
    fields = {
        "active": True,
        "discount": None,
        "rates": [1, 2.5, {"kind": "fixed"}],
        "metadata": {"region": "EU", "priority": 4},
    }
    with patch.dict(os.environ, {"CONTRACT_SIGNING_KEY": "nested-key"}, clear=False):
        assert create_contract_signature("C-103", 0, fields) == expected_signature(
            "nested-key", "C-103", 0, fields
        )


def test_version_and_contract_id_are_part_of_signature():
    fields = {"status": "draft"}
    with patch.dict(os.environ, {"CONTRACT_SIGNING_KEY": "identity-key"}, clear=False):
        original = create_contract_signature("C-104", 1, fields)
        assert original == expected_signature("identity-key", "C-104", 1, fields)
        assert create_contract_signature("C-105", 1, fields) != original
        assert create_contract_signature("C-104", 2, fields) != original


def test_different_keys_produce_different_signatures():
    fields = {"name": "Master Services Agreement"}
    with patch.dict(os.environ, {"CONTRACT_SIGNING_KEY": "first-key"}, clear=False):
        first = create_contract_signature("C-106", 1, fields)
    with patch.dict(os.environ, {"CONTRACT_SIGNING_KEY": "second-key"}, clear=False):
        second = create_contract_signature("C-106", 1, fields)
    assert first == expected_signature("first-key", "C-106", 1, fields)
    assert second == expected_signature("second-key", "C-106", 1, fields)
    assert first != second

