import hmac
import json
import os

def create_contract_signature(contract_id: str, version: int, fields: dict[str, object]) -> str:
    key = os.environ.get('CONTRACT_SIGNING_KEY')
    if not key:
        raise ValueError('CONTRACT_SIGNING_KEY is required')
    message = json.dumps({'contract_id': contract_id, 'version': version, 'fields': fields}, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode('utf-8')
    return hmac.new(key.encode('utf-8'), message, hashlib.sha256).hexdigest()

