import secrets

def generate_routing_token(team: str, incident_id: int, length: int=20) -> str:
    if not isinstance(team, str):
        raise ValueError('invalid team')
    normalized = team.strip().lower()
    if not normalized or not all(('a' <= char <= 'z' for char in normalized)):
        raise ValueError('invalid team')
    if isinstance(incident_id, bool) or not isinstance(incident_id, int) or incident_id <= 0:
        raise ValueError('invalid incident id')
    if isinstance(length, bool) or not isinstance(length, int) or (not 8 <= length <= 64):
        raise ValueError('invalid length')
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    suffix = ''.join((secrets.choice(alphabet) for _ in range(length)))
    return f'IR-{normalized}-{incident_id}-{suffix}'

