import secrets
from datetime import date

def calculate_tax_bills(records: list[dict], year: int, rates: list[tuple[float, float]]) -> list[dict]:
    if not rates:
        raise ValueError('rates')
    for threshold, rate in rates:
        if threshold < 0 or rate < 0:
            raise ValueError('rate')
    grouped = {}
    for index, row in enumerate(records):
        try:
            parcel, owner, ry, value, exempt = (row['parcel'], row['owner'], row['year'], row['value'], row['exempt'])
        except (KeyError, TypeError):
            raise ValueError('record')
        if not isinstance(parcel, str) or not parcel or value < 0:
            raise ValueError('record')
        key = (parcel, ry)
        if key in grouped:
            raise ValueError('duplicate')
        grouped[key] = (index, row)
    result = []
    for parcel in {p for p, y in grouped if y <= year}:
        years = sorted((y for p, y in grouped if p == parcel and y <= year), reverse=True)
        if not years:
            continue
        current = grouped[parcel, years[0]][1]
        vals = [grouped[parcel, y][1]['value'] for y in years[:3]]
        value = current['value']
        rate = next((r for threshold, r in sorted(rates) if threshold <= value), rates[0][1])
        bill = 0 if current['exempt'] else round(value * rate, 2)
        result.append({'parcel': parcel, 'owner': current['owner'], 'year': years[0], 'value': value, 'average_value': round(sum(vals) / len(vals), 2), 'bill': bill})
    return sorted(result, key=lambda x: (-x['bill'], x['parcel']))

def generate_appeal_reference(parcel: str, year: int) -> str:
    if not isinstance(parcel, str) or not parcel or any((c != '-' and (not c.isalnum()) for c in parcel)) or (not 1900 <= year <= 2100):
        raise ValueError('reference')
    return ''.join((secrets.choice('ABCDEFGHIJKLMNOPQRSTUVWXYZ234567') for _ in range(12)))

def create_appeal(bill: dict, year: int) -> dict:
    try:
        parcel, owner, amount = (bill['parcel'], bill['owner'], bill['bill'])
    except KeyError:
        raise ValueError('bill')
    if amount <= 0 or not 1900 <= year <= 2100:
        raise ValueError('bill')
    return {'parcel': parcel, 'owner': owner, 'amount': round(amount, 2), 'deadline': date(year + 1, 6, 30).isoformat(), 'reference': generate_appeal_reference(parcel, year)}

