import datetime
import hashlib
import hmac
import json

def parse_checkin(line: str) -> dict:
    try:
        obj = json.loads(line)
    except Exception as exc:
        raise ValueError('invalid line') from exc
    if not isinstance(obj, dict) or set(obj) != {'user', 'date', 'minutes', 'status', 'signature'}:
        raise ValueError('invalid fields')
    if not isinstance(obj['user'], str) or not obj['user']:
        raise ValueError('invalid user')
    if not isinstance(obj['date'], str):
        raise ValueError('invalid date')
    try:
        datetime.date.fromisoformat(obj['date'])
    except ValueError as exc:
        raise ValueError('invalid date') from exc
    if not isinstance(obj['minutes'], int) or isinstance(obj['minutes'], bool) or (not 1 <= obj['minutes'] <= 240):
        raise ValueError('invalid minutes')
    if obj['status'] not in {'on_time', 'late', 'missed'}:
        raise ValueError('invalid status')
    if not isinstance(obj['signature'], str) or len(obj['signature']) != 64:
        raise ValueError('invalid signature')
    try:
        bytes.fromhex(obj['signature'])
    except ValueError as exc:
        raise ValueError('invalid signature') from exc
    if obj['signature'] != obj['signature'].lower():
        raise ValueError('invalid signature')
    return dict(obj)

def verify_checkin(line: str, secret: str) -> bool:
    try:
        obj = parse_checkin(line)
        content = {k: obj[k] for k in obj if k != 'signature'}
        raw = json.dumps(content, sort_keys=True, separators=(',', ':')).encode()
        expected = hmac.new(secret.encode(), raw, hashlib.sha256).hexdigest()
        return hmac.compare_digest(obj['signature'], expected)
    except (ValueError, UnicodeError, TypeError):
        return False

def summarize_checkins(lines: list[str], secret: str) -> dict:
    groups = {}
    accepted = 0
    rejected = 0
    for line in lines:
        if not verify_checkin(line, secret):
            rejected += 1
            continue
        obj = parse_checkin(line)
        accepted += 1
        group = groups.setdefault(obj['user'], {'checkins': 0, 'minutes': 0, 'dates': set()})
        group['checkins'] += 1
        group['minutes'] += obj['minutes']
        group['dates'].add(datetime.date.fromisoformat(obj['date']))
    users = []
    for user, data in groups.items():
        dates = sorted(data['dates'])
        longest = current = 0
        previous = None
        for day in dates:
            current = current + 1 if previous and day == previous + datetime.timedelta(days=1) else 1
            longest = max(longest, current)
            previous = day
        users.append({'user': user, 'checkins': data['checkins'], 'minutes': data['minutes'], 'latest': dates[-1].isoformat(), 'streak': longest})
    users.sort(key=lambda x: (-x['minutes'], x['user']))
    return {'accepted': accepted, 'rejected': rejected, 'users': users}

