from lxml import etree

def _read(xml):
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        return etree.fromstring(xml.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc

def parse_ocr(xml: str) -> dict:
    root = _read(xml)
    if root.tag != 'document':
        raise ValueError('root must be document')
    pages = []
    seen = set()
    all_conf = []
    for page in root.findall('page'):
        try:
            number = int(page.get('number'))
        except (TypeError, ValueError):
            raise ValueError('invalid page number')
        if number < 0 or number in seen:
            raise ValueError('invalid page number')
        seen.add(number)
        lines = []
        for li, line in enumerate(page.findall('line')):
            try:
                y = float(line.get('y', '0'))
            except ValueError:
                raise ValueError('invalid y')
            words = []
            for wi, word in enumerate(line.findall('word')):
                try:
                    text = word.attrib['text']
                    conf = float(word.attrib['confidence'])
                    x = float(word.attrib['x'])
                except (KeyError, ValueError):
                    raise ValueError('invalid word')
                if not 0 <= conf <= 1:
                    raise ValueError('invalid confidence')
                words.append((x, wi, text, conf))
                all_conf.append(conf)
            words.sort(key=lambda z: (z[0], z[1]))
            lines.append((y, li, ' '.join((w[2] for w in words)), [w[3] for w in words]))
        lines.sort(key=lambda z: (z[0], z[1]))
        values = [v for line in lines for v in line[3]]
        pages.append((number, '\n'.join((line[2] for line in lines)), len(values), values))
    pages.sort(key=lambda z: z[0])
    result = []
    for number, text, count, values in pages:
        result.append({'number': number, 'text': text, 'word_count': count, 'confidence': round(sum(values) / count, 3) if count else 0.0})
    return {'pages': result, 'text': '\x0c'.join((p['text'] for p in result)), 'average_confidence': round(sum(all_conf) / len(all_conf), 3) if all_conf else 0.0}

def score_ocr(xml: str, threshold: float=0.75) -> dict:
    if not isinstance(threshold, (int, float)) or isinstance(threshold, bool) or (not 0 <= threshold <= 1):
        raise ValueError('invalid threshold')
    data = parse_ocr(xml)
    return {'total_words': sum((p['word_count'] for p in data['pages'])), 'mean_confidence': data['average_confidence'], 'pages_below_threshold': [p['number'] for p in data['pages'] if p['confidence'] < threshold], 'reading_time_seconds': round(sum((p['word_count'] for p in data['pages'])) / 2.5, 2)}

