def list_material_totals(conn: sqlite3.Connection, search: str='', min_weight: float=0.0, sort_by: str='total_weight', descending: bool=False, limit: int=10, offset: int=0) -> list[dict]:
    if not isinstance(search, str):
        raise TypeError('search must be a string')
    if not isinstance(descending, bool):
        raise TypeError('descending must be a boolean')
    if not isinstance(limit, int) or isinstance(limit, bool):
        raise TypeError('limit must be an integer')
    if not isinstance(offset, int) or isinstance(offset, bool):
        raise TypeError('offset must be an integer')
    if not isinstance(min_weight, (int, float)) or isinstance(min_weight, bool) or (not math.isfinite(min_weight)) or (min_weight < 0):
        raise ValueError('invalid minimum weight')
    if sort_by not in {'material', 'count', 'total_weight'}:
        raise ValueError('invalid sort field')
    if limit <= 0:
        raise ValueError('limit must be positive')
    if offset < 0:
        raise ValueError('offset must be nonnegative')
    rows = conn.execute('SELECT material, COUNT(*), SUM(weight_kg) FROM materials WHERE instr(material, ?) > 0 AND weight_kg >= ? GROUP BY material', (search, min_weight)).fetchall()
    values = [{'material': material, 'count': count, 'total_weight': round(total, 2)} for material, count, total in rows]
    if sort_by == 'material':
        values.sort(key=lambda item: item['material'], reverse=descending)
    else:
        values.sort(key=lambda item: (item[sort_by], item['material']), reverse=False)
        if descending:
            values.sort(key=lambda item: item[sort_by], reverse=True)
            values.sort(key=lambda item: item['material'])
    return values[offset:offset + limit]

