import hashlib
import math
import os

def hash_access_code(code: str) -> str:
    if not isinstance(code, str) or not code.strip():
        raise ValueError('code must be a non-empty string')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', code.encode(), salt, 100000)
    return 'pbkdf2:100000:' + salt.hex() + ':' + digest.hex()

def verify_access_code(code: str, stored_hash: str) -> bool:
    if not isinstance(code, str) or not isinstance(stored_hash, str):
        return False
    parts = stored_hash.split(':')
    if len(parts) != 4 or parts[0] != 'pbkdf2':
        return False
    try:
        iterations = int(parts[1])
        salt = bytes.fromhex(parts[2])
        expected = bytes.fromhex(parts[3])
    except ValueError:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', code.encode(), salt, iterations)
    return actual == expected

def build_beneficiary_report(records: list[dict], region: str | None=None, page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)):
        raise ValueError('invalid pagination')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    groups = {}
    for record in records:
        amount = record['amount']
        if isinstance(amount, bool) or not isinstance(amount, (int, float)) or (not math.isfinite(amount)) or (amount < 0):
            raise ValueError('invalid amount')
        if record['approved'] is True and (region is None or record['region'] == region):
            key = record['region']
            if key not in groups:
                groups[key] = [0, 0.0]
            groups[key][0] += 1
            groups[key][1] += amount
    items = [{'region': key, 'beneficiary_count': value[0], 'total_amount': round(value[1], 2)} for key, value in groups.items()]
    items.sort(key=lambda item: (-item['total_amount'], item['region']))
    start = (page - 1) * page_size
    return {'total_regions': len(items), 'page': page, 'page_size': page_size, 'items': items[start:start + page_size]}

