import hmac
import os
import math
from datetime import datetime, timezone

def _credential(pin):
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return '100000$' + salt.hex() + '$' + digest.hex()

def _check(pin, value):
    try:
        count, salt, digest = value.split('$')
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), bytes.fromhex(salt), int(count)).hex()
        return hmac.compare_digest(actual, digest)
    except (AttributeError, ValueError, TypeError):
        return False

def create_sensor_record(sensor_id: str, pin: str) -> dict:
    if not isinstance(sensor_id, str) or not sensor_id or (not isinstance(pin, str)) or (not pin):
        raise ValueError('invalid sensor credentials')
    return {'sensor_id': sensor_id, 'credential': _credential(pin), 'readings': []}

def authenticate_sensor(record: dict, pin: str) -> bool:
    if not isinstance(record, dict) or not isinstance(pin, str):
        return False
    return _check(pin, record.get('credential'))

def parse_readings(text: str) -> list[dict]:
    if not isinstance(text, str):
        raise ValueError('invalid text')
    rows = list(csv.reader((line for line in text.splitlines() if line.strip())))
    if not rows or rows[0] != ['timestamp', 'moisture', 'temperature'] or len(rows) == 1:
        raise ValueError('invalid header or empty data')
    output = []
    seen = set()
    for row in rows[1:]:
        if len(row) != 3:
            raise ValueError('invalid row')
        try:
            value = datetime.fromisoformat(row[0].replace('Z', '+00:00'))
            if value.tzinfo is None or value.utcoffset() != timezone.utc.utcoffset(value):
                raise ValueError('timezone required')
            stamp = value.astimezone(timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')
            moisture, temperature = (float(row[1]), float(row[2]))
        except Exception as exc:
            raise ValueError('invalid reading') from exc
        if not math.isfinite(moisture) or not math.isfinite(temperature) or (not 0 <= moisture <= 100) or (stamp in seen):
            raise ValueError('invalid reading')
        seen.add(stamp)
        output.append({'timestamp': stamp, 'moisture': moisture, 'temperature': temperature})
    output.sort(key=lambda x: x['timestamp'])
    return output

def aggregate_readings(readings: list[dict], window_minutes: int=60) -> list[dict]:
    if not isinstance(window_minutes, int) or isinstance(window_minutes, bool) or (not 1 <= window_minutes <= 1440):
        raise ValueError('invalid window')
    groups = {}
    for item in readings:
        try:
            stamp = datetime.fromisoformat(item['timestamp'].replace('Z', '+00:00')).astimezone(timezone.utc)
            moisture, temperature = (float(item['moisture']), float(item['temperature']))
        except Exception as exc:
            raise ValueError('invalid reading') from exc
        if not math.isfinite(moisture) or not math.isfinite(temperature):
            raise ValueError('invalid reading')
        minute = (stamp.hour * 60 + stamp.minute) // window_minutes * window_minutes
        start = stamp.replace(hour=minute // 60, minute=minute % 60, second=0, microsecond=0)
        groups.setdefault(start, []).append((moisture, temperature))
    result = []
    for start in sorted(groups):
        values = groups[start]
        result.append({'start': start.strftime('%Y-%m-%dT%H:%M:%SZ'), 'count': len(values), 'average_moisture': round(sum((x[0] for x in values)) / len(values), 2), 'minimum_temperature': round(min((x[1] for x in values)), 2), 'maximum_temperature': round(max((x[1] for x in values)), 2)})
    return result

def ingest_sensor_readings(record: dict, pin: str, text: str, window_minutes: int=60) -> list[dict]:
    if not authenticate_sensor(record, pin):
        raise PermissionError('authentication failed')
    parsed = parse_readings(text)
    aggregate_readings(record['readings'] + parsed, window_minutes)
