from datetime import datetime

def _time(value):
    try:
        return datetime.strptime(value, '%Y-%m-%dT%H:%M:%SZ')
    except Exception as exc:
        raise ValueError('invalid timestamp') from exc

def _read(path):
    with open(path, encoding='utf-8') as handle:
        return handle.read().splitlines()

def summarize_uld_events(path: str, cutoff: str | None=None) -> list[dict]:
    limit = _time(cutoff) if cutoff is not None else None
    events = []
    for raw in _read(path):
        if not raw.strip():
            continue
        parts = raw.split('|')
        if len(parts) != 5:
            raise ValueError('malformed event')
        stamp, uld, flight, status, weight_text = parts
        when = _time(stamp)
        if not uld or not flight or status not in {'LOAD', 'UNLOAD', 'HOLD', 'RELEASE'}:
            raise ValueError('invalid event')
        try:
            weight = int(weight_text)
        except Exception as exc:
            raise ValueError('invalid weight') from exc
        if weight < 0 or (status in {'LOAD', 'UNLOAD'} and weight == 0) or (status in {'HOLD', 'RELEASE'} and weight != 0):
            raise ValueError('invalid weight')
        if limit is None or when <= limit:
            events.append((uld, when, stamp, flight, status, weight))
    events.sort(key=lambda event: (event[0], event[1]))
    states = {}
    for uld, when, stamp, flight, status, weight in events:
        state = states.setdefault(uld, {'weight_kg': 0, 'flights': [], 'seen': set(), 'event_count': 0})
        if status == 'LOAD':
            state['weight_kg'] += weight
        elif status == 'UNLOAD':
            state['weight_kg'] -= weight
            if state['weight_kg'] < 0:
                raise ValueError('negative weight')
        if flight not in state['seen']:
            state['seen'].add(flight)
            state['flights'].append(flight)
        state['event_count'] += 1
        state['last_status'] = status
        state['last_timestamp'] = stamp
    return [{'uld_id': uld, 'last_status': s['last_status'], 'last_timestamp': s['last_timestamp'], 'weight_kg': s['weight_kg'], 'flights': s['flights'], 'event_count': s['event_count']} for uld, s in states.items()]

def render_tracking_report(rows: list[dict]) -> str:
