def export_appointments(records: list[dict], destination: str, country: str | None=None, page: int=1, page_size: int=20) -> dict:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('invalid pagination')
    selected = []
    for record in records:
        try:
            identifier = record['id']
            applicant = record['applicant']
            record_country = record['country']
            date_text = record['date']
            status = record['status']
            fee = record['fee']
            if not isinstance(identifier, str) or not identifier or (not isinstance(applicant, str)) or (not isinstance(record_country, str)) or (not record_country) or (not isinstance(status, str)):
                raise ValueError('invalid record')
            datetime.date.fromisoformat(date_text)
            if isinstance(fee, bool) or not isinstance(fee, (int, float)) or fee < 0:
                raise ValueError('invalid fee')
            fee_decimal = Decimal(str(fee))
            if not fee_decimal.is_finite():
                raise ValueError('invalid fee')
        except (KeyError, TypeError, ValueError, InvalidOperation):
            raise ValueError('invalid record')
        if status == 'confirmed' and (country is None or record_country == country):
            selected.append((date_text, identifier, applicant, record_country, fee_decimal))
    selected.sort(key=lambda item: (item[0], item[1]))
    total = len(selected)
    start = (page - 1) * page_size
    rows = selected[start:start + page_size]
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='appointments-', suffix='.csv', dir=directory)
    try:
