            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['appointment_id', 'applicant', 'country', 'date', 'fee'])
            for _, identifier, applicant, record_country, fee_decimal in rows:
                writer.writerow([identifier, applicant, record_country, _, f"{fee_decimal.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP):.2f}"])
        os.replace(temporary, destination)
    except Exception:
