        raise ValueError('page must be positive')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('page_size must be positive')
    grouped = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        site = record.get('site')
        link_id = record.get('link_id')
        length = record.get('length_km')
        attenuation = record.get('attenuation_db')
        if not isinstance(site, str) or not site or (not isinstance(link_id, str)) or (not link_id) or isinstance(length, bool) or (not isinstance(length, (int, float))) or (length < 0) or isinstance(attenuation, bool) or (not isinstance(attenuation, (int, float))) or (attenuation < 0):
