def _check(events, limits):
    if not isinstance(limits, dict):
        raise ValueError('invalid limits')
    for user, limit in limits.items():
        if not isinstance(user, str) or not user or isinstance(limit, bool) or (not isinstance(limit, int)) or (limit < 0):
            raise ValueError('invalid limits')
    checked = []
    for event in events:
        if not isinstance(event, dict) or set(event) != {'user', 'timestamp', 'delta'}:
            raise ValueError('invalid event')
        user, stamp, delta = (event['user'], event['timestamp'], event['delta'])
        if not isinstance(user, str) or not user or user not in limits:
            raise ValueError('invalid user')
        if isinstance(delta, bool) or not isinstance(delta, int) or delta < 0:
            raise ValueError('invalid delta')
        try:
            parsed = datetime.datetime.fromisoformat(stamp)
        except (TypeError, ValueError):
            raise ValueError('invalid timestamp')
        checked.append((parsed, len(checked), user, delta))
    return checked

def compute_quota(events, limits):
    checked = _check(events, limits)
    usage = {user: 0 for user in limits}
    peak = {user: 0 for user in limits}
    for _, _, user, delta in sorted(checked, key=lambda x: x[0]):
        usage[user] += delta
