def evaluate_expression(expression: str, variables: dict[str, int | float | bool]) -> int | float | bool:
    tree = ast.parse(expression, mode='eval')
    allowed = (ast.Expression, ast.Constant, ast.Name, ast.BinOp, ast.UnaryOp, ast.BoolOp, ast.Compare, ast.Add, ast.Sub, ast.Mult, ast.Div, ast.USub, ast.UAdd, ast.Not, ast.And, ast.Or, ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE, ast.Call, ast.Load)
    for node in ast.walk(tree):
        if not isinstance(node, allowed):
            raise ValueError('unsupported expression')
        if isinstance(node, ast.Constant) and (not isinstance(node.value, (int, float, bool))):
            raise ValueError('unsupported literal')
        if isinstance(node, ast.Call):
            if not isinstance(node.func, ast.Name) or node.func.id not in ('min', 'max', 'round') or node.keywords:
                raise ValueError('unsupported function')

    def run(node):
        if isinstance(node, ast.Expression):
            return run(node.body)
        if isinstance(node, ast.Constant):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in variables:
                raise NameError(node.id)
            return variables[node.id]
        if isinstance(node, ast.BinOp):
            a, b = (run(node.left), run(node.right))
            if isinstance(node.op, ast.Add):
                return a + b
            if isinstance(node.op, ast.Sub):
                return a - b
            if isinstance(node.op, ast.Mult):
                return a * b
            return a / b
        if isinstance(node, ast.UnaryOp):
            value = run(node.operand)
            if isinstance(node.op, ast.USub):
                return -value
            if isinstance(node.op, ast.UAdd):
                return value
            return not value
        if isinstance(node, ast.BoolOp):
            value = run(node.values[0])
            for part in node.values[1:]:
                if isinstance(node.op, ast.And) and (not value):
                    return value
                if isinstance(node.op, ast.Or) and value:
                    return value
                value = run(part)
            return value
        if isinstance(node, ast.Compare):
            left = run(node.left)
            for op, item in zip(node.ops, node.comparators):
                right = run(item)
                if isinstance(op, ast.Eq):
                    good = left == right
                elif isinstance(op, ast.NotEq):
                    good = left != right
                elif isinstance(op, ast.Lt):
                    good = left < right
                elif isinstance(op, ast.LtE):
                    good = left <= right
                elif isinstance(op, ast.Gt):
                    good = left > right
                else:
                    good = left >= right
                if not good:
                    return False
                left = right
            return True
        if isinstance(node, ast.Call):
            return {'min': min, 'max': max, 'round': round}[node.func.id](*[run(x) for x in node.args])
    return run(tree)

def process_permits(records: list[dict], rules: dict[str, str], capacities: dict[str, int], as_of: int) -> dict:
    ids = [r['id'] for r in records]
    if len(ids) != len(set(ids)):
        raise ValueError('duplicate id')
    candidates = []
    for r in records:
        if r['zone'] in rules and r['zone'] in capacities and (r['expires'] >= as_of):
            values = dict(r)
            values['as_of'] = as_of
            if evaluate_expression(rules[r['zone']], values):
                candidates.append(r)
    candidates.sort(key=lambda r: (-r['priority'], r['expires'], r['id']))
    remaining = dict(capacities)
    used = {z: 0 for z in capacities}
    approved = []
    approved_set = set()
    total = 0
    for r in candidates:
        z = r['zone']
        if r['requested_spaces'] <= remaining[z]:
            remaining[z] -= r['requested_spaces']
            used[z] += r['requested_spaces']
            approved.append(r['id'])
            approved_set.add(r['id'])
            total += r['fee'] * r['requested_spaces']
    return {'approved': approved, 'rejected': [i for i in ids if i not in approved_set], 'spaces_by_zone': used, 'fee_total': total}

