def make_report(body, secret="audit-key"):
    if isinstance(body, dict):
        body = json.dumps(body, separators=(",", ":"), ensure_ascii=False)
    key = secret.encode() if isinstance(secret, str) else secret
    sig = hmac.new(key, body.encode("utf-8"), hashlib.sha256).hexdigest()
    return "signature=" + sig + "\n" + body

def test_empty_report_has_stable_shape():
    assert verify_report(make_report({"findings": []}), "audit-key") == {"total": 0, "by_severity": {"critical": 0, "high": 0, "medium": 0, "low": 0}, "open_controls": [], "findings": []}

