        record("b", date="2025-04-10", status="cancelled"),
        record("c", date="2025-04-20"),
        record("d", date="2025-04-30"),
    ])
    result = build_inspection_agenda(payload, signed(payload), "building-key", "2025-04-10", "2025-04-20")
