import hashlib
import hmac
import json
import re
from datetime import date

def build_inspection_agenda(payload: str, signature_header: str, signing_key: str, start_date: str, end_date: str) -> list[dict]:
    if not re.fullmatch('sha256=[0-9a-f]{64}', signature_header):
        raise ValueError('invalid signature header')
    expected = hmac.new(signing_key.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest().encode('ascii')
    supplied = signature_header[7:].encode('ascii')
    if not hmac.compare_digest(expected, supplied):
        raise PermissionError('signature mismatch')
    try:
        begin = date.fromisoformat(start_date)
        finish = date.fromisoformat(end_date)
    except (TypeError, ValueError):
        raise ValueError('invalid date range')
    if start_date != begin.isoformat() or end_date != finish.isoformat() or begin > finish:
        raise ValueError('invalid date range')
    try:
        document = json.loads(payload)
    except (TypeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    if not isinstance(document, dict) or not isinstance(document.get('inspections'), list):
        raise ValueError('invalid inspections')
    seen = set()
    selected = []
    for item in document['inspections']:
        if not isinstance(item, dict) or any((not isinstance(item.get(k), str) or not item[k] for k in ('id', 'address', 'inspector', 'date', 'status'))):
            raise ValueError('invalid inspection')
        if item['id'] in seen:
            raise ValueError('duplicate id')
        seen.add(item['id'])
        try:
            inspection_date = date.fromisoformat(item['date'])
        except ValueError:
            raise ValueError('invalid inspection date')
        if item['date'] != inspection_date.isoformat():
            raise ValueError('invalid inspection date')
        if item['status'] == 'scheduled' and begin <= inspection_date <= finish:
            selected.append({k: item[k] for k in ('id', 'address', 'inspector', 'date')})
    selected.sort(key=lambda x: (x['date'], x['inspector'].casefold(), x['id']))
    return selected

