import xml.etree.ElementTree as ET
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def summarize_visa_applications(xml_text: str, page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('invalid paging')
    try:
        root = ET.fromstring(xml_text)
    except Exception as exc:
        raise ValueError('invalid xml') from exc
    if root.tag != 'visa_applications':
        raise ValueError('invalid root')
    rows = []
    ids = set()
    for node in root.findall('application'):
        values = {}
        for name in ('id', 'country', 'visa_type', 'status', 'fee'):
            child = node.find(name)
            if child is None or child.text is None or (not child.text.strip()):
                raise ValueError('invalid application')
            values[name] = child.text.strip()
        if values['id'] in ids:
            raise ValueError('duplicate id')
        ids.add(values['id'])
        try:
            fee = Decimal(values['fee']).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        except (InvalidOperation, ValueError):
            raise ValueError('invalid fee')
        if fee < 0:
            raise ValueError('invalid fee')
        values['fee'] = fee
        rows.append(values)
    rows.sort(key=lambda x: (-x['fee'], x['id']))
    counts = {}
    for row in rows:
        counts[row['country']] = counts.get(row['country'], 0) + 1
    start = (page - 1) * page_size
    selected = rows[start:start + page_size]
    applications = [{**row, 'fee': float(row['fee'])} for row in selected]
    total = sum((row['fee'] for row in rows), Decimal('0.00')).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    return {'total': len(rows), 'page': page, 'page_size': page_size, 'applications': applications, 'by_country': dict(sorted(counts.items())), 'total_fees': float(total)}

