import ast
import operator

def _evaluate(text, values):
    tree = ast.parse(text, mode='eval').body
    functions = {'min': min, 'max': max, 'round': round}
    binary = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
    comparisons = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}

    def visit(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool, str)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id in values:
                return values[node.id]
            if node.id in functions:
                return functions[node.id]
            raise NameError(node.id)
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = visit(node.operand)
            return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
        if isinstance(node, ast.BinOp) and type(node.op) in binary:
            return binary[type(node.op)](visit(node.left), visit(node.right))
        if isinstance(node, ast.BoolOp):
            value = visit(node.values[0])
            for part in node.values[1:]:
                if isinstance(node.op, ast.And):
                    if not value:
                        return value
                elif value:
                    return value
                value = visit(part)
            return value
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            for op, part in zip(node.ops, node.comparators):
                if type(op) not in comparisons:
                    raise ValueError('unsupported expression')
                right = visit(part)
                if not comparisons[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in functions) and (not node.keywords):
            return functions[node.func.id](*(visit(arg) for arg in node.args))
        raise ValueError('unsupported expression')
    return visit(tree)

def rank_robot_diagnostics(records: list[dict], rule: str, score: str, limit: int=10) -> list[dict]:
    if isinstance(limit, bool) or not isinstance(limit, int) or (not 0 <= limit <= 1000):
        raise ValueError('invalid limit')
    selected = []
    for record in records:
        values = {key: record[key] for key in ('id', 'status', 'temperature', 'vibration', 'cycles')}
        if _evaluate(rule, values):
            value = _evaluate(score, values)
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise TypeError('score must be numeric')
            selected.append((value, record['id']))
    selected.sort(key=lambda item: (-item[0], item[1]))
    return [{'id': identifier, 'score': round(value, 2), 'severity': 'critical' if value >= 90 else 'warning' if value >= 70 else 'normal'} for value, identifier in selected[:limit]]

