        raise ValueError('invalid service date')
    matches = [card for card in cards if card.get('id') == card_id]
    if not matches:
        raise KeyError(card_id)
    if len(matches) > 1:
        raise ValueError('duplicate card')
    card = matches[0]
    if not (requester.get('id') == card.get('owner_id') or (requester.get('role') == 'inspector' and requester.get('tenant_id') == card.get('tenant_id'))):
        raise PermissionError('permission denied')
    selected = []
    for trip in trips:
        if trip.get('card_id') == card_id and trip.get('service_date') == service_date and (trip.get('status') == 'completed'):
            fare = trip.get('fare_cents')
            if type(fare) is not int or fare < 0:
                raise ValueError('invalid fare')
            selected.append(trip)
    selected.sort(key=lambda trip: (trip['timestamp'], trip['id']))
    remaining = 700
    result_trips = []
    for trip in selected:
        charge = min(trip['fare_cents'], remaining)
        remaining -= charge
        result_trips.append({'id': trip['id'], 'charged_cents': charge})
    return {'card_id': card_id, 'service_date': service_date, 'trip_count': len(selected), 'charged_cents': 700 - remaining, 'trips': result_trips}

