import calendar
from datetime import datetime

def build_fuel_report(requester: dict, cards: list[dict], transactions: list[dict], month: str) -> dict:
    if len(month) != 7 or month[4] != '-' or (not month[:4].isdigit()) or (not month[5:].isdigit()):
        raise ValueError('invalid month')
    year = int(month[:4])
    number = int(month[5:])
    if number < 1 or number > 12:
        raise ValueError('invalid month')
    if requester.get('role') != 'fleet_manager' and (not requester.get('user_id')):
        raise PermissionError('access denied')
    card_map = {}
    for card in cards:
        if card['card_id'] in card_map:
            raise ValueError('duplicate card')
        card_map[card['card_id']] = card
    if requester.get('role') == 'fleet_manager':
        allowed = requester.get('tenant_id')
    else:
        allowed = requester.get('user_id')
    groups = {}
    total_liters = 0.0
    total_cents = 0
    for transaction in transactions:
        card_id = transaction['card_id']
        if card_id not in card_map:
            raise ValueError('unknown card')
        if transaction['liters'] < 0 or transaction['amount_cents'] < 0:
            raise ValueError('negative value')
        card = card_map[card_id]
        if card['tenant_id'] != requester.get('tenant_id'):
            continue
        if requester.get('role') != 'fleet_manager' and card['owner_id'] != allowed:
            continue
        timestamp = datetime.fromisoformat(transaction['timestamp'])
        if timestamp.year != year or timestamp.month != number:
            continue
        vehicle = card['vehicle_id']
        item = groups.setdefault(vehicle, [0.0, 0, 0])
        item[0] += transaction['liters']
        item[1] += transaction['amount_cents']
        item[2] += 1
        total_liters += transaction['liters']
        total_cents += transaction['amount_cents']
    vehicles = [{'vehicle_id': vehicle, 'liters': round(values[0], 3), 'cost_cents': values[1], 'transaction_count': values[2]} for vehicle, values in groups.items()]
    vehicles.sort(key=lambda item: (-item['cost_cents'], item['vehicle_id']))
    return {'month': month, 'currency': 'USD', 'total_cents': total_cents, 'total_liters': round(total_liters, 3), 'vehicles': vehicles}

