import datetime

def _date(value):
    try:
        return datetime.date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def parse_event(text: str) -> dict:
    if not isinstance(text, str):
        raise ValueError('event must be text')
    fields, current, escaped = ([], [], False)
    for char in text:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    fields.append(''.join(current))
    if len(fields) != 3:
        raise ValueError('bad event')
    day = _date(fields[0])
    kind = fields[1]
    if kind not in ('visit', 'water', 'harvest'):
        raise ValueError('bad kind')
    if kind == 'visit':
        if fields[2] != '':
            raise ValueError('visit amount')
        return {'day': day, 'kind': kind}
    try:
        amount = float(fields[2])
    except (TypeError, ValueError):
        raise ValueError('bad amount')
    if amount < 0 or amount != amount:
        raise ValueError('bad amount')
    return {'day': day, 'kind': kind, 'amount': amount}

def _event(value):
    if isinstance(value, str):
        return parse_event(value)
    if not isinstance(value, dict):
        raise ValueError('bad event')
    day = _date(value.get('day'))
    kind = value.get('kind')
    if kind not in ('visit', 'water', 'harvest'):
        raise ValueError('bad kind')
    if kind == 'visit':
        if 'amount' in value:
            raise ValueError('visit amount')
        return {'day': day, 'kind': kind}
    amount = value.get('amount')
    if isinstance(amount, bool) or not isinstance(amount, (int, float)) or amount < 0:
        raise ValueError('bad amount')
    return {'day': day, 'kind': kind, 'amount': float(amount)}

def summarize_plot_activity(garden: dict, requester: dict, start_day: str, end_day: str) -> list[dict]:
    start, end = (_date(start_day), _date(end_day))
    if start > end:
        raise ValueError('reversed range')
    result = []
