        priority = item.get('priority')
        if not isinstance(district, str) or not district or (not isinstance(quantity, int)) or isinstance(quantity, bool) or (quantity < 0) or (not isinstance(priority, int)) or isinstance(priority, bool) or (not 1 <= priority <= 5):
