from datetime import date, timedelta
import requests

def _dates(a, b):
    try:
        start = date.fromisoformat(a)
        end = date.fromisoformat(b)
    except (TypeError, ValueError):
        raise ValueError('invalid dates')
    if end <= start:
        raise ValueError('check_out must be later')
    return (start, end)

def fetch_room_options(hotel_id: str, check_in: str, check_out: str, guests: int) -> list[dict]:
    start, end = _dates(check_in, check_out)
    if not isinstance(guests, int) or isinstance(guests, bool) or guests <= 0:
        raise ValueError('invalid guests')
    r = requests.get('https://reservations.example.com/hotels/' + str(hotel_id) + '/availability', params={'check_in': check_in, 'check_out': check_out, 'guests': guests}, headers={'Accept': 'application/json'}, timeout=10)
    if r.status_code != 200:
        raise RuntimeError('availability request failed: ' + str(r.status_code))
    try:
        body = r.json()
    except Exception as e:
        raise ValueError('invalid JSON') from e
    if not isinstance(body, dict) or not isinstance(body.get('rooms'), list):
        raise ValueError('invalid rooms')
    wanted = [start + timedelta(days=i) for i in range((end - start).days)]
    out = []
    for room in body['rooms']:
        try:
            if not room['available'] or room['capacity'] < guests:
                continue
            rates = room['nightly_rates']
            mapping = {x['date']: x['amount'] for x in rates}
            if set(mapping) != {x.isoformat() for x in wanted}:
                continue
            amounts = list(mapping.values())
            if any((not isinstance(x, (int, float)) or isinstance(x, bool) for x in amounts + room['fees'])):
                continue
            nightly = round(sum(amounts), 2)
            fees = round(sum(room['fees']), 2)
            out.append({'room_id': room['room_id'], 'category': room['category'], 'capacity': room['capacity'], 'rating': room['rating'], 'amenities': sorted(room['amenities']), 'nights': len(wanted), 'nightly_total': nightly, 'fee_total': fees, 'total': round(nightly + fees, 2)})
        except (KeyError, TypeError, ValueError):
            continue
    return sorted(out, key=lambda x: (x['total'], -x['rating'], x['room_id']))

def select_best_room(options: list[dict], required_amenities: tuple[str, ...]=()) -> dict | None:
    if not isinstance(required_amenities, tuple) or not all((isinstance(x, str) for x in required_amenities)):
        raise ValueError('invalid amenities')
    eligible = [x for x in options if set(required_amenities).issubset(x.get('amenities', []))]
