import math

def render_fulfillment_report(records: list[dict], page: int=1, page_size: int=20) -> str:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('invalid page size')
    required = ('order_id', 'customer', 'product', 'quantity', 'price', 'status')
    ready = []
    for record in records:
        if not isinstance(record, dict) or any((key not in record for key in required)):
            raise ValueError('invalid record')
        if any((not isinstance(record[key], str) for key in ('order_id', 'customer', 'product', 'status'))):
            raise ValueError('invalid text field')
        quantity = record['quantity']
        price = record['price']
        if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity <= 0:
            raise ValueError('invalid quantity')
        if isinstance(price, bool) or not isinstance(price, (int, float)) or price < 0 or (not math.isfinite(price)):
            raise ValueError('invalid price')
        if record['status'] == 'ready':
            ready.append(record)
    ready.sort(key=lambda r: (r['customer'], r['order_id'], r['product']))
    total_units = sum((r['quantity'] for r in ready))
    total_value = sum((r['quantity'] * r['price'] for r in ready))
    total = len(ready)
    pages = max(1, math.ceil(total / page_size))
    start = (page - 1) * page_size
    shown = ready[start:start + page_size]
    rows = ''.join((f"<tr><td>{r['order_id']}</td><td>{r['customer']}</td><td>{r['product']}</td><td>{r['quantity']}</td><td>${r['price']:.2f}</td><td>${r['quantity'] * r['price']:.2f}</td></tr>" for r in shown))
    return f'<div class="report"><h1>Fulfillment Report</h1><p class="summary">Showing {len(shown)} of {total} ready items | Units: {total_units} | Value: ${total_value:.2f}</p><table><thead><tr><th>Order</th><th>Customer</th><th>Product</th><th>Quantity</th><th>Unit Price</th><th>Line Total</th></tr></thead><tbody>{rows}</tbody></table><p class="page">Page {page} of {pages}</p></div>'
